<script setup>
import { $api } from '@/utils/api'

const requests=ref([]), error=ref(''), busy=ref(false), selected=ref(null), completeOpen=ref(false), externalReference=ref('')
const money=(v,c='ZAR')=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:c}).format((v||0)/100)
async function load(){error.value='';try{requests.value=(await $api('/booking/refund-requests')).data}catch(e){error.value=e?.data?.message||'Refund review is available to central finance administrators.'}}
function openComplete(item){selected.value=item;externalReference.value='';completeOpen.value=true}
async function complete(){busy.value=true;error.value='';try{await $api(`/booking/refund-requests/${selected.value.id}/complete`,{method:'POST',body:{external_reference:externalReference.value}});completeOpen.value=false;await load()}catch(e){error.value=e?.data?.message||'Refund could not be completed.'}finally{busy.value=false}}
onMounted(load)
</script>
<template><div><div class="mb-6"><h3 class="text-h3">Booking refund review</h3><p class="text-medium-emphasis">Policy-calculated refund entitlements awaiting manual finance processing.</p></div><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert><VCard><VTable><thead><tr><th>Booking</th><th>Member</th><th>Invoice / payment</th><th>Policy</th><th>Entitlement</th><th>Owners</th><th>Status</th><th/></tr></thead><tbody><tr v-for="item in requests" :key="item.id"><td>{{item.booking.booking_reference}}<br><small>{{item.booking.facility.name}}</small></td><td>#{{item.member_id}}</td><td>{{item.invoice.invoice_number}}<br><small>{{item.payment?.payment_reference||'No linked payment'}}</small></td><td>{{item.compensation.policy_band.replaceAll('_',' ')}} · {{item.compensation.compensation_percentage}}%</td><td>{{money(item.entitlement_amount,item.currency)}}</td><td><div v-for="owner in item.financial_owner_breakdown" :key="`${owner.financial_owner_type}-${owner.sport_code_id}`">{{owner.financial_owner_type.replaceAll('_',' ')}}: {{money(owner.amount,item.currency)}}</div></td><td>{{item.status.replaceAll('_',' ')}}</td><td><VBtn v-if="item.status==='pending_finance_review'" size="small" @click="openComplete(item)">Complete</VBtn><small v-else>{{item.external_reference}}</small></td></tr></tbody></VTable></VCard><VDialog v-model="completeOpen" max-width="520" persistent><VCard v-if="selected"><VCardTitle class="pa-6">Record processed refund</VCardTitle><VCardText><VAlert type="info" class="mb-4">The amount is fixed at {{money(selected.entitlement_amount,selected.currency)}} by the booking cancellation policy.</VAlert><VTextField v-model="externalReference" label="Bank or processor reference"/></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" :disabled="busy" @click="completeOpen=false">Cancel</VBtn><VBtn :loading="busy" :disabled="!externalReference.trim()" @click="complete">Mark processed</VBtn></VCardActions></VCard></VDialog></div></template>
